package esercizi_1;

public class es_1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		/*
		 * Scrivi un programma che verifichi se un numero intero sia positivo, negativo oppure zero.
		 */
		
		int numero = 0;
		
		if(numero < 0)
		{
			System.out.println("Il numero " + numero + " è negativo.");
		}
		else if(numero == 0 )
		{
			System.out.println("Il numero " + numero + " è uguale a zero.");
		}
		else
		System.out.println("Il numero " + numero + " è positivo.");
		
	}
/*
 * voto 9/10
 */
}

